-- Fictional values solely for testing the editable plan interface. They are not
-- field recommendations. No pesticide products, rates or schedules are supplied.
UPDATE management_plans SET rain_needed_months=(SELECT c.rain_needed_months FROM area_season_varieties av JOIN varieties v ON v.id=av.variety_id JOIN crops c ON c.id=v.crop_id WHERE av.id=management_plans.area_season_variety_id),
 rain_requirement_notes='Fictional test duration only; rain distribution and intensity are unknown.',
 weeding_count=2, fertility_notes='Example quantities are fictional UI test values; use a locally reviewed soil-based plan.'
WHERE (title LIKE 'Demo plan: %' AND overall_notes='Fictional plan for interface testing, dated 2025-01-15. Confirm each step with a local extension officer.') OR (title='Demo management plan' AND overall_notes='Fictional steps for testing; consult local extension advice.');
UPDATE management_stages SET start_day_after_planting=CASE stage_name WHEN 'Land preparation' THEN -14 WHEN 'Planting' THEN 0 WHEN 'Establishment' THEN 7 WHEN 'Crop management' THEN 28 WHEN 'Harvest' THEN (SELECT CASE WHEN v.maturity_days IS NOT NULL THEN max(0,v.maturity_days-10) END FROM management_plans p JOIN area_season_varieties av ON av.id=p.area_season_variety_id JOIN varieties v ON v.id=av.variety_id WHERE p.id=management_stages.management_plan_id) END,
 end_day_after_planting=CASE stage_name WHEN 'Land preparation' THEN -1 WHEN 'Planting' THEN 0 WHEN 'Establishment' THEN 14 WHEN 'Crop management' THEN 60 WHEN 'Harvest' THEN (SELECT v.maturity_days FROM management_plans p JOIN area_season_varieties av ON av.id=p.area_season_variety_id JOIN varieties v ON v.id=av.variety_id WHERE p.id=management_stages.management_plan_id) END,
 timing_notes='Fictional test timing relative to planting; not field guidance.'
WHERE management_plan_id IN (SELECT id FROM management_plans WHERE (title LIKE 'Demo plan: %' AND overall_notes='Fictional plan for interface testing, dated 2025-01-15. Confirm each step with a local extension officer.') OR (title='Demo management plan' AND overall_notes='Fictional steps for testing; consult local extension advice.'));
INSERT OR IGNORE INTO management_stages(management_plan_id,stage_order,stage_name,description,weather_rain_needs,activities,start_day_after_planting,end_day_after_planting,timing_notes,activity_type,weeding_round)
SELECT id,6,'First weeding','Sample first weed check and removal.', 'Avoid working waterlogged soil.', '["Inspect weeds", "Remove weeds where appropriate"]',14,21,'Fictional timing for testing; confirm locally.','weeding',1 FROM management_plans WHERE rain_requirement_notes='Fictional test duration only; rain distribution and intensity are unknown.';
INSERT OR IGNORE INTO management_stages(management_plan_id,stage_order,stage_name,description,weather_rain_needs,activities,start_day_after_planting,end_day_after_planting,timing_notes,activity_type,weeding_round)
SELECT id,7,'Second weeding','Sample second weed check and removal.', 'Consider soil moisture and field accessibility.', '["Inspect weeds", "Remove weeds where appropriate"]',35,42,'Fictional timing for testing; confirm locally.','weeding',2 FROM management_plans WHERE rain_requirement_notes='Fictional test duration only; rain distribution and intensity are unknown.';
INSERT OR IGNORE INTO management_stages(management_plan_id,stage_order,stage_name,description,weather_rain_needs,activities,start_day_after_planting,end_day_after_planting,timing_notes,activity_type)
SELECT id,8,'Fertility review','Example fertilizer entry for testing the plan interface.', 'Consider current soil moisture; verify advice locally.', '["Review soil results with an extension officer"]',21,28,'Fictional timing for testing; confirm locally.','fertilizer' FROM management_plans WHERE rain_requirement_notes='Fictional test duration only; rain distribution and intensity are unknown.';
INSERT OR IGNORE INTO inputs(name,unit,category) VALUES ('Test fertilizer placeholder','kg','Fertilizer');
INSERT OR IGNORE INTO stage_inputs(management_stage_id,input_id,quantity_per_acre,notes)
SELECT ms.id,i.id,10,'Fictional test number only. Do not apply; obtain a locally reviewed soil-based rate.' FROM management_stages ms JOIN management_plans p ON p.id=ms.management_plan_id JOIN inputs i ON i.name='Test fertilizer placeholder' WHERE ms.stage_name='Fertility review' AND p.rain_requirement_notes='Fictional test duration only; rain distribution and intensity are unknown.';
INSERT OR IGNORE INTO stage_treatments(management_stage_id,treatment_type,name,timing_notes,guidance,source_id)
SELECT ms.id,'non_chemical','Crop health observation','At the crop-management stage','Inspect the crop and consult a qualified extension officer if symptoms appear.',p.source_id FROM management_stages ms JOIN management_plans p ON p.id=ms.management_plan_id WHERE ms.stage_name='Crop management' AND p.rain_requirement_notes='Fictional test duration only; rain distribution and intensity are unknown.' AND p.source_id IS NOT NULL;
